    for group in dict.fromkeys(d['group'] for d in reviewed):
        lines += ['### '+group, '', '| Документ | Страниц | Адресат и использование | Редакция / точные места |', '|---|---:|---|---|']
        for d in reviewed:
            if d['group']!=group:continue
            lines.append(f"| [{d['title']}]({d['id']}.pdf) · [официальный файл]({d['url']}) · [текст JSON]({d['id']}.json) | {d['page_count']} | {d['audience']}. {d['use_and_limitations']} | {d['version_note']}. {d['key_locators']} |")
